<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Notification\Message\Infrastructure\Driven;

use Psr\EventDispatcher\EventDispatcherInterface;
use Closure;
use Override;
use Throwable;
use Civi\Lughauth\Features\Notification\Message\Domain\Gateway\MessageWriteGateway;
use Civi\Lughauth\Features\Notification\Message\Infrastructure\Connector\Pdo\MessagePdoConnector;
use Civi\Lughauth\Features\Notification\Message\Domain\Gateway\MessageSlide;
use Civi\Lughauth\Features\Notification\Message\Domain\Gateway\MessageCursor;
use Civi\Lughauth\Features\Notification\Message\Domain\Gateway\MessageFilter;
use Civi\Lughauth\Features\Notification\Message\Domain\MessageRef;
use Civi\Lughauth\Features\Notification\Message\Domain\Message;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;
use Civi\Lughauth\Shared\Infrastructure\EntityChangelog\EntityChangelogService;

class MessageWriteRepositoryAdapter implements MessageWriteGateway
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly MessagePdoConnector $conn,
        private readonly EventDispatcherInterface $dispatcher,
        private readonly EntityChangelogService $changelog,
    ) {
    }
    #[Override]
    public function resolveForUpdate(MessageRef $ref): ?Message
    {
        return $this->conn->retrieveForUpdate(new MessageFilter(uids: [ $ref->uid() ]));
    }
    #[Override]
    public function listForUpdate(?MessageFilter $filter = null, ?MessageCursor $cursor = null): MessageSlide
    {
        $this->logDebug("List for update of Message on adapter ");
        $span = $this->startSpan("List for update of Message on adapter");
        try {
            $values = $this->conn->listForUpdate($filter, $cursor);
            $last = end($values);
            return new MessageSlide(function (MessageSlide $slide, ?MessageCursor$next) use ($filter) {
                return $this->listForUpdate($filter, $next);
            }, new MessageCursor($cursor?->limit() ?? 100, false !== $last ? $last->uid() : null), $values);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function retrieveForUpdate(MessageFilter $filter): ?Message
    {
        $this->logDebug("Retrieve for update of Message on adapter ");
        $span = $this->startSpan("Retrieve for update of Message on adapter");
        try {
            return $this->conn->retrieveForUpdate($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function existsForUpdate(MessageFilter $filter): bool
    {
        $this->logDebug("Exists for update of Message on adapter ");
        $span = $this->startSpan("Exists for update of Message on adapter");
        try {
            return $this->conn->existsForUpdate($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function countForUpdate(?MessageFilter $filter = null): int
    {
        $this->logDebug("Count for update of Message on adapter ");
        $span = $this->startSpan("Count for update of Message on adapter");
        try {
            return $this->conn->countForUpdate($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function create(Message $entity, ?Closure $verify = null): Message
    {
        $this->logDebug("Count for Message on adapter ");
        $span = $this->startSpan("Count for Message on adapter");
        try {
            $created = $this->conn->create($entity, $verify);
            $this->dispatch($entity);
            $this->changelog->recordChange('message', $entity->uid() ?? 'no-id', $entity->asPublicJson());
            return $created;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function update(MessageRef $ref, Message $entity): Message
    {
        $this->logDebug("Count for Message on adapter ");
        $span = $this->startSpan("Count for Message on adapter");
        try {
            $updated = $this->conn->update($entity);
            $this->dispatch($entity);
            $this->changelog->recordChange('message', $entity->uid() ?? 'no-id', $entity->asPublicJson());
            return $updated;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    #[Override]
    public function delete(Message $entity): bool
    {
        $this->logDebug("Count for Message on adapter ");
        $span = $this->startSpan("Count for Message on adapter");
        try {
            $result = $this->conn->delete($entity);
            $this->dispatch($entity);
            $this->changelog->recordDeletion('message', $entity->uid() ?? 'no-id', $entity->asPublicJson());
            return $result;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    private function dispatch(Message $entity): void
    {
        $this->logDebug("Count for Message on adapter ");
        $span = $this->startSpan("Count for Message on adapter");
        try {
            foreach ($entity->getTheEvents() as $event) {
                $this->dispatcher->dispatch($event);
            }
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
